import {STATIONS,validStation} from './ui-navigation.js?v=5274ca0d14f4';
export function stationPanel(state,ready,escape) {
  const station=STATIONS.find(value=>value.id===validStation(state.station));
  return `<div class="na-panel-heading"><button data-action="close-secondary" aria-label="返回上一页">‹</button><div><small>站内多楼层 · 官方模型与示意模型</small><h1>站内 3D</h1></div></div><div class="na-station-picker" role="group" aria-label="选择车站">${STATIONS.map(value=>`<button data-station="${value.id}" aria-pressed="${station.id===value.id}">${value.name}</button>`).join('')}</div><p class="na-note">${ready?`${station.name}站 · 拖动旋转，双指缩放；可筛选楼层、分层展开。`:'站体资料正在加载，准备好后会自动显示。'}</p><div class="na-station-actions"><button class="na-secondary" data-action="station-plan">从此站出发</button><button class="na-secondary" data-tab="info">数据说明</button></div><p class="na-note">楼层模型用于查看空间结构，不代表通道已核验或设施实时开放。${station.id==='KOW'?'九龙站部分站体为示意，不能作为通行依据。':station.id==='EXC'?'会展站提供模型查看，未提供已核验的进出站路径。':'米数是来源高程，并非层高或地下深度。'}</p>${state.origin||state.destination?`<p class="na-station-trip">当前行程：${escape(state.origin?.name??'未选起点')} → ${escape(state.destination?.name??'未选终点')}</p>`:''}`;
}
export function informationPanel() {
  return `<div class="na-panel-heading"><button data-action="close-secondary" aria-label="返回上一页">‹</button><div><small>覆盖范围 · 数据来源 · 使用边界</small><h1>数据与使用说明</h1></div></div><div class="na-service-banner">MaaS 本机演示。无真实售票、调度或扣款；时间与费用均为估算。</div><section class="na-info-section"><h2>联程规划</h2><p>步行、地铁、公交与电车自动组合全程，可选择是否加入出租车接续。综合推荐会考虑时间、费用、候车、步行与换乘负担。</p><p>普通出行、行李少搬运、扶梯优先、升降机优先和严格无障碍共五种偏好，均在同一规划界面设置。严格无障碍遇到核验缺口不会换成普通路线。</p><button class="na-secondary" data-tab="home">返回出行规划</button></section><section class="na-info-section"><h2>站体与楼层</h2><p>金钟、红磡、柯士甸及会展的站体和室内几何来自官方三维数据；九龙部分模型为示意。路线是否可走由路网和核验条件决定，地图图形不建立通行连接。</p><p>红磡出口地面 G、大堂 C 与行人道 C 是源标记；屯马 G／东铁 L1 需与港铁站图对照。会展 P 指出口平台，不是列车月台。铁路线段只表示拓扑，车门及停车位置未核验。</p><button class="na-secondary" data-tab="station">查看站内 3D</button></section><section class="na-info-section"><h2>地图覆盖与实时性</h2><p>当前轨道联程只建模金钟—红磡—柯士甸，尚未包含荃湾线等完整香港地铁网络。返回的是已载入网络内的方案，不能视为现实香港全网最优路线。</p><p>步行路网、交通站点及站体以已载入范围为准。金钟街区底图使用官方建筑及 1:1,000／1:5,000 图形；水域与植被来自 1:50,000 地形图，只作地理背景。</p><p>虚线表示接续关系，不能沿直线穿越建筑或水面。模拟班次、车辆位置、订单与接驳时间不代表实时运营，设施状态请以现场指示为准。</p></section><section class="na-info-section"><h2>官方来源</h2><a href="https://portal.csdi.gov.hk/csdi-webpage/apidoc/3d-indoor-mtr-station-map" target="_blank" rel="noreferrer">地政总署三维站体数据 ↗</a><a href="https://portal.csdi.gov.hk/csdi-webpage/doc/TNC" target="_blank" rel="noreferrer">地政总署使用条款 ↗</a><div class="na-source-links">${[['adm','金钟'],['huh','红磡'],['aus','柯士甸'],['kow','九龙'],['exc','会展']].map(([id,name])=>`<a href="https://www.mtr.com.hk/archive/ch/services/layouts/${id}.pdf" target="_blank" rel="noreferrer">${name}站图 ↗</a>`).join('')}</div></section><section class="na-info-section"><h2>账户与服务</h2><p>订单、模拟票证、演示积分和偏好统一在此浏览器管理。不会把用户资料发送给交通运营商，正式运营仍需授权接口、身份认证与服务端事务。</p><div class="na-station-actions"><button class="na-secondary" data-tab="account">账户与隐私</button><button class="na-secondary" data-tab="services">服务设置</button></div></section>`;
}
